import de.sebaro_ventures.design.icons.SebaroIcons

/**
 * D131 (CHECKS.md §75): 5–8 steps always use numbered markers and the stepOf + current-word line, at every width.
 * Step indicator (spec/02 §3.12): [steps] are the words (2 to 4 keep D101 (1)), [current] the 0-based current
 * step; steps before it are done, steps after it are next; current == steps.size means all done. [showHead] shows
 * „Schritt n von m“. While every word fits its column on two lines (hyphenated only when it is wider than the column,
 * as SbWrapText draws it, measured at the current step's weight: provisional, agent) each word stands under its bar; else (D100 (1),
 * D101 (1), (2)) the bars stay, the checks stay under the done bars, and only the current step's word stands on its own
 * line over the full width under the bars, start-aligned. TalkBack hears every step's word and state either way.
 * It chooses the form from its width (a BoxWithConstraints), so it cannot stand in a parent that asks for intrinsic
 * sizes (IntrinsicSize, spec/08 §17).
 */
@Composable
fun SbSteps(steps: List<String>, current: Int, modifier: Modifier = Modifier, showHead: Boolean = true) {
    require(steps.isNotEmpty()) { "SbSteps: no steps" }
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val m = sbMessages()
    val measurer = rememberTextMeasurer()
    val strong = ty.caption.copy(fontWeight = ty.title.fontWeight)
    // the step the head names: the current one, or the last when all are done
    val named = current.coerceIn(0, steps.lastIndex)
    BoxWithConstraints(modifier.fillMaxWidth()) {
        // D101 (1): the same limit as the segments (two lines), with the hyphen of D99 (1) for a word wider than its
        // column; whichever step is current, so the form does not change from step to step
        val words = steps.size < 5 && with(LocalDensity.current) {
            val column = ((constraints.maxWidth - t.space.s1.roundToPx() * (steps.size - 1)) / steps.size).coerceAtLeast(1)
            steps.all { word ->
                val split = measurer.sbWidestWord(word, strong) > column
                val style = if (split) strong.copy(hyphens = Hyphens.Auto, lineBreak = LineBreak.Simple) else strong
                measurer.measure(word, style, constraints = Constraints(maxWidth = column)).lineCount <= 2
            }
        }
        Column(Modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(t.space.s2)) {
            if (showHead && steps.size < 5) {
                Text(m.stepOf(sbFormatCount(named + 1), sbFormatCount(steps.size)), style = ty.caption, color = c.text)
            }
            Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(t.space.s1)) {
                steps.forEachIndexed { index, word ->
                    val done = index < current
                    val now = index == current
                    val edge = when {
                        now -> c.accent
                        done -> c.text
                        else -> c.border
                    }
                    val ink = when {
                        now -> c.link
                        done -> c.text
                        else -> c.textMuted
                    }
                    val segment = Modifier
                        .weight(1f)
                        .sbCurrentEdge(true, SbEdge.Top, edge, t.borderWidth.strong)
                    // the node holds the bar too, so a segment without a check still has a size for TalkBack
                    val inside = Modifier.padding(top = t.borderWidth.strong + t.space.s2)
                    val check: @Composable (Modifier) -> Unit = { place ->
                        Icon(SebaroIcons.Outline16.Check, contentDescription = null, tint = ink, modifier = place.size(t.size.iconSm))
                    }
                    if (words) {
                        // D99 (1): the word goes under the check when it does not fit beside it, and only a word wider
                        // than the whole column is hyphenated (four steps on a phone: „Erinnerung“)
                        SbFlowRow(
                            segment
                                .semantics(mergeDescendants = true) {
                                    if (done) stateDescription = m.stepDone
                                    if (now) stateDescription = m.stepCurrent
                                }
                                .then(inside),
                            horizontalArrangement = Arrangement.spacedBy(t.space.s1),
                        ) {
                            if (done) check(Modifier.align(Alignment.CenterVertically))
                            SbWrapText(word, if (now) strong else ty.caption, ink, Modifier.align(Alignment.CenterVertically))
                        }
                    } else {
                        // D101 (2): the bar and, under a done one, its check; the word is the segment's for TalkBack
                        Box(
                            segment
                                .semantics(mergeDescendants = true) {
                                    this[SemanticsProperties.Text] = listOf(AnnotatedString(word))
                                    if (done) stateDescription = m.stepDone
                                    if (now) stateDescription = m.stepCurrent
                                }
                                .then(inside),
                        ) {
                            if (steps.size >= 5) {
                                // D131: the check replaces a done number, so nothing wraps under it at 200 %
                                if (done) check(Modifier)
                                else Text(sbFormatCount(index + 1), softWrap = false, color = ink,
                                    style = if (now) strong.copy(textDecoration = androidx.compose.ui.text.style.TextDecoration.Underline) else ty.caption)
                            } else if (done) check(Modifier)
                        }
                    }
                }
            }
            if (!words) {
                // the named step's word under all bars, start-aligned; TalkBack has it on its segment already
                val now = named == current
                SbWrapText(
                    if (steps.size >= 5) m.stepOf(sbFormatCount(named + 1), sbFormatCount(steps.size)) + " · " + steps[named] else steps[named],
                    if (now) strong else ty.caption,
                    if (now) c.link else c.text,
                    Modifier.fillMaxWidth().clearAndSetSemantics { },
                )
            }
        }
    }
}
